{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "공원부지사용계약을 맺은 땅 주인이 사용료를 언제, 어떻게 받는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "공원관리청은 공원부지사용계약에 따른 부지사용료를 토지소유자의 청구에 따라 지급하여야 한다. 토지소유자는 계약한 날부터 1년 단위(1년 미만 단위는 그 계약기간만큼을 계산)로 부지사용료 지급을 청구하여야 한다. 공원관리청은 지급청구를 받은 날로부터 30일 이내에 토지소유자가 지정하는 은행계좌에 현금으로 입금하는 것을 원칙으로 한다. 다만, 부지사용료 지급시기와 방법은 토지소유자와 공원관리청이 협의하여 조정할 수 있다.",
          "b_ids": "도시공원:제30조제4호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
